# Let's look for interesting strings in the binary and try to understand the validation logic
# The binary is UPX packed, but we can look at the embedded data

import re

target = "{TARGET}"

with open(target, 'rb') as f:
    data = f.read()

# Look for ASCII strings
strings = []
current = b""
for i, b in enumerate(data):
    if 32 <= b < 127:
        current += bytes([b])
    else:
        if len(current) >= 4:
            try:
                strings.append((i - len(current), current.decode('ascii')))
            except:
                pass
        current = b""

# Print interesting strings
for offset, s in strings:
    if 'flag' in s.lower() or 'correct' in s.lower() or 'wrong' in s.lower() or 'accept' in s.lower() or 'input' in s.lower():
        print(f"0x{offset:x}: {s}")

print("\n--- All strings longer than 10 chars ---")
for offset, s in strings:
    if len(s) > 10 and not all(c in '0123456789abcdefx' for c in s.lower()):
        print(f"0x{offset:x}: {s[:80]}")

# Let me try a different approach - look at the actual code execution
# Since this is UPX-packed with WASM, the validation logic is in the decompressed code
# Let me use angr to find the check function

import angr
import claripy

target = "{TARGET}"
proj = angr.Project(target, auto_load_libs=False, load_options={'main_opts': {'base_addr': 0}})

# Let's look for functions that contain comparison loops
# or functions that reference the "flag:" string area

# First, find xrefs to the data region around 0x26a30
cfg = proj.analyses.CFGFast()

# Look for references to the string data
data_addr = 0x26a30
print(f"Looking for references to 0x{data_addr:x}")

# Check if this address is in any function
for func_addr, func in cfg.functions.items():
    if hasattr(func, 'block_addrs'):
        for block_addr in func.block_addrs:
            try:
                block = proj.factory.block(block_addr)
                # Check if any instruction references our data
                for insn in block.capstone.insns:
                    if data_addr in insn.operands:
                        print(f"Found ref in function 0x{func_addr:x}: {insn}")
            except:
                pass

# Let's instead look for functions that do input validation
# by searching for functions that have many comparison instructions
print("\n--- Functions with many comparisons ---")
for func_addr, func in list(cfg.functions.items())[:100]:
    try:
        cmp_count = 0
        for block_addr in func.block_addrs:
            try:
                block = proj.factory.block(block_addr)
                for insn in block.capstone.insns:
                    if insn.mnemonic in ['cmp', 'test']:
                        cmp_count += 1
            except:
                pass
        if cmp_count > 5:
            print(f"0x{func_addr:x}: {cmp_count} comparisons")
    except:
        pass
